// Wraps the OpenNext-generated worker so a Cron Trigger can run daily maintenance.
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`.
import handler from './.open-next/worker.js';

export default {
  fetch: handler.fetch,
  async scheduled(_event, env, ctx) {
    // Reuse the app's own code path (and auth) instead of bundling server modules twice.
    const request = new Request(`${env.PUBLIC_SITE_URL}/api/cron/daily`, {
      method: 'POST',
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    ctx.waitUntil(handler.fetch(request, env, ctx));
  },
} satisfies ExportedHandler<CloudflareEnv>;
